#include "CloseToHSL/Core/Runtime/Events/Hypercalls/YAKSys_Hybrid_CPU.Core.HypercallBackendDescriptor.h"
#include "CloseToHSL/Core/Runtime/Capabilities/Descriptors/YAKSys_Hybrid_CPU.Core.CapabilityDescriptorSet.h"
#include "CloseToHSL/Core/Runtime/Domains/Descriptors/EvidencePolicy/YAKSys_Hybrid_CPU.Core.EvidencePolicyDescriptor.h"
#include <cassert>
using namespace YAKSys_Hybrid_CPU::Core;
int main(){ auto trap=NeutralTrapResult::Trap(TrapRequest::ForInstruction(259,1),NeutralTrapResultKind::InstructionIntercept); auto admission=RuntimeBoundaryAdmissionResult::Allowed(DomainRuntimeAuthorityResult::Allowed); auto caps=CapabilityDescriptorSet::getEmpty(); auto evidence=std::make_shared<EvidencePolicyDescriptor>(true,true,true); auto svc=HypercallBackendAdmissionService::getDefault(); auto missing=HypercallBackendAdmissionRequest::MissingNeutralOwner(trap,admission,caps,evidence,true); assert(svc->Admit(missing)->Decision==HypercallBackendAdmissionDecision::MissingBackendDescriptor); auto cap=CapabilityBoundaryRequirement::None; auto ev=std::make_shared<EvidenceBoundaryRequirement>(EvidenceBoundaryRequirement::None); auto descriptor=HypercallBackendDescriptor::RuntimeOwnedDesignFence(cap,ev); auto req=std::make_shared<HypercallBackendAdmissionRequest>(trap,admission,descriptor,caps,evidence,true); assert(svc->Admit(req)->Decision==HypercallBackendAdmissionDecision::DeniedNeutralBackendOwnerMissing); auto draft=HypercallBackendDescriptor::RuntimeOwnedDraftOwnerFence(cap,ev,NeutralHypercallBackendOwnerDescriptor::DraftNoStateCandidate(3)); auto dreq=std::make_shared<HypercallBackendAdmissionRequest>(trap,admission,draft,caps,evidence,true); auto result=svc->Admit(dreq); assert(result->Decision==HypercallBackendAdmissionDecision::DeniedNeutralBackendOwnerRfcAdr && result->DeniesBackendExecution); auto noTests=HypercallBackendDescriptor::RuntimeOwnedDraftOwnerFence(cap,ev,NeutralHypercallBackendOwnerDescriptor::DraftNoStateCandidate(3,false)); assert(svc->Admit(std::make_shared<HypercallBackendAdmissionRequest>(trap,admission,noTests,caps,evidence,true))->Decision==HypercallBackendAdmissionDecision::DeniedNeutralBackendOwnerProof); }
